    default_deployment, SLOT,
};
use crate::support::run;

const TARGET_NODE: &str = "node.canary-rebind-target";

pub(super) fn assert_rejected(cwd: &Path, authorization: &str) {
    let output = default_deployment::rebind_placement_raw(cwd, authorization, TARGET_NODE);
    assert!(!output.status.success());
    assert!(output.stderr.is_empty());
    let value: JsonValue = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(value["accepted"], false);
    assert_eq!(value["target_placement_entry_current"], JsonValue::Null);
    assert_eq!(value["placement_currentness_changed"], false);
    assert!(!run(
        cwd,
        [
            "program",
            "module",
            "foreign-process",
            "placement",
            "inspect",
            "--slot",
            SLOT,
            "--node-id",
            TARGET_NODE,
            "--format",
